import { readFileSync, readdirSync, statSync } from 'fs';
import { join, extname, basename } from 'path';
import yaml from 'js-yaml';
import { Marked } from 'marked';
import { Frontmatter, Post } from './types';
import { highlightCode } from './highlight';

const marked = new Marked();

marked.use({
  renderer: {
    code({ text, lang }: { text: string; lang?: string }) {
      return highlightCode(text, lang);
    },
  },
});

export function parseFrontmatter(raw: string): { frontmatter: Frontmatter; body: string } {
  const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  if (!match) {
    throw new Error('No valid frontmatter found');
  }

  const parsed = yaml.load(match[1]);
  if (!parsed || typeof parsed !== 'object') {
    throw new Error('Invalid frontmatter YAML');
  }

  const fm = parsed as Record<string, unknown>;
  if (typeof fm.title !== 'string' || !fm.title.trim()) {
    throw new Error('Frontmatter must contain a non-empty title');
  }

  const frontmatter: Frontmatter = {
    title: fm.title,
    date: typeof fm.date === 'string' ? fm.date : undefined,
    tags: Array.isArray(fm.tags) ? fm.tags.map(String) : undefined,
    draft: typeof fm.draft === 'boolean' ? fm.draft : undefined,
    layout: typeof fm.layout === 'string' ? fm.layout : undefined,
  };

  for (const key of Object.keys(fm)) {
    if (!(key in frontmatter)) {
      frontmatter[key] = fm[key];
    }
  }

  return { frontmatter, body: match[2] };
}

export function parseMarkdown(raw: string): { frontmatter: Frontmatter; html: string } {
  const { frontmatter, body } = parseFrontmatter(raw);
  const html = marked.parse(body) as string;
  return { frontmatter, html };
}

function slugify(filename: string): string {
  return basename(filename, extname(filename))
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

export function collectMarkdownFiles(dir: string): string[] {
  const files: string[] = [];

  function walk(d: string) {
    for (const entry of readdirSync(d)) {
      const full = join(d, entry);
      const st = statSync(full);
      if (st.isDirectory()) {
        walk(full);
      } else if (extname(entry) === '.md') {
        files.push(full);
      }
    }
  }

  walk(dir);
  return files;
}

export function parsePosts(sourceDir: string): Post[] {
  const files = collectMarkdownFiles(sourceDir);
  const posts: Post[] = [];

  for (const file of files) {
    try {
      const raw = readFileSync(file, 'utf-8');
      const { frontmatter, html } = parseMarkdown(raw);
      if (frontmatter.draft) continue;

      const slug = slugify(file);
      posts.push({
        frontmatter,
        content: raw,
        html,
        slug,
        sourcePath: file,
      });
    } catch {
      // skip unparseable files
    }
  }

  posts.sort((a, b) => {
    const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
    const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
    return db - da;
  });

  return posts;
}

import hljs from 'highlight.js';

export function highlightCode(code: string, lang?: string): string {
  if (lang && hljs.getLanguage(lang)) {
    try {
      const result = hljs.highlight(code, { language: lang });
      return `<pre><code class="hljs language-${lang}">${result.value}</code></pre>`;
    } catch {
      // fall through to auto-detection
    }
  }

  try {
    const result = hljs.highlightAuto(code);
    if (result.language) {
      return `<pre><code class="hljs language-${result.language}">${result.value}</code></pre>`;
    }
  } catch {
    // fall through to plain
  }

  return `<pre><code>${escapeHtml(code)}</code></pre>`;
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

import {
  existsSync,
  mkdirSync,
  readdirSync,
  writeFileSync,
  copyFileSync,
  statSync,
} from 'fs';
import { join, dirname, extname } from 'path';

export function ensureDir(dir: string): void {
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }
}

export function writeFile(path: string, content: string): void {
  ensureDir(dirname(path));
  writeFileSync(path, content, 'utf-8');
}

export function copyStaticFiles(sourceDir: string, outputDir: string): void {
  if (!existsSync(sourceDir)) return;

  function walk(src: string, dest: string) {
    ensureDir(dest);
    for (const entry of readdirSync(src)) {
      if (entry.startsWith('_')) continue;

      const srcPath = join(src, entry);
      const destPath = join(dest, entry);
      const st = statSync(srcPath);

      if (st.isDirectory()) {
        walk(srcPath, destPath);
      } else if (extname(entry) !== '.md') {
        copyFileSync(srcPath, destPath);
      }
    }
  }

  walk(sourceDir, outputDir);
}

import { readFileSync, readdirSync, existsSync } from 'fs';
import { join, extname, basename } from 'path';
import Handlebars from 'handlebars';
import { Post, SiteConfig, TemplateData } from './types';

interface Templates {
  layout: Handlebars.TemplateDelegate | null;
  post: Handlebars.TemplateDelegate | null;
  index: Handlebars.TemplateDelegate | null;
  tag: Handlebars.TemplateDelegate | null;
  partials: Record<string, Handlebars.TemplateDelegate>;
}

export function loadTemplates(templatesDir: string): Templates {
  const partialsDir = join(templatesDir, 'partials');
  const templates: Templates = {
    layout: null,
    post: null,
    index: null,
    tag: null,
    partials: {},
  };

  if (existsSync(partialsDir)) {
    for (const f of readdirSync(partialsDir)) {
      if (extname(f) === '.hbs' || extname(f) === '.handlebars') {
        const name = basename(f, extname(f));
        const src = readFileSync(join(partialsDir, f), 'utf-8');
        Handlebars.registerPartial(name, src);
        templates.partials[name] = Handlebars.compile(src);
      }
    }
  }

  function load(name: string): Handlebars.TemplateDelegate | null {
    for (const ext of ['.hbs', '.handlebars']) {
      const p = join(templatesDir, name + ext);
      if (existsSync(p)) {
        const src = readFileSync(p, 'utf-8');
        return Handlebars.compile(src);
      }
    }
    return null;
  }

  templates.layout = load('layout');
  templates.post = load('post');
  templates.index = load('index');
  templates.tag = load('tag');

  return templates;
}

export function renderPage(
  templates: Templates,
  post: Post,
  config: SiteConfig,
  allPosts: Post[],
  isDev: boolean,
): string {
  const td: TemplateData = {
    site: { title: config.siteTitle, url: config.siteUrl },
    page: {
      title: post.frontmatter.title,
      date: post.frontmatter.date || '',
      tags: post.frontmatter.tags || [],
      content: post.html,
      slug: post.slug,
    },
    posts: [post],
  };

  const postTemplate = templates.post || templates.layout;
  if (!postTemplate) {
    throw new Error('No post or layout template found');
  }

  let body = postTemplate(td);

  if (templates.layout && postTemplate !== templates.layout) {
    body = templates.layout({
      ...td,
      page: { ...td.page, content: body },
    });
  }

  if (isDev) {
    body = injectReload(body);
  }

  return body;
}

export function renderIndex(
  templates: Templates,
  posts: Post[],
  config: SiteConfig,
  isDev: boolean,
): string {
  const template = templates.index || templates.layout;
  if (!template) {
    throw new Error('No index or layout template found');
  }

  const td: TemplateData = {
    site: { title: config.siteTitle, url: config.siteUrl },
    page: { title: 'Home', slug: 'index' },
    posts,
  };

  let body = template(td);

  if (templates.layout && template !== templates.layout) {
    body = templates.layout({
      ...td,
      page: { ...td.page, content: body },
    });
  }

  if (isDev) {
    body = injectReload(body);
  }

  return body;
}

export function renderTagPage(
  templates: Templates,
  tag: string,
  tagPosts: Post[],
  config: SiteConfig,
  isDev: boolean,
): string {
  const template = templates.tag || templates.index || templates.layout;
  if (!template) {
    throw new Error('No suitable template found for tag page');
  }

  const td: TemplateData = {
    site: { title: config.siteTitle, url: config.siteUrl },
    page: { title: `Tag: ${tag}`, slug: `tags/${tag}` },
    posts: tagPosts,
    currentTag: tag,
  };

  let body = template(td);

  if (templates.layout && template !== templates.layout) {
    body = templates.layout({
      ...td,
      page: { ...td.page, content: body },
    });
  }

  if (isDev) {
    body = injectReload(body);
  }

  return body;
}

const RELOAD_SCRIPT =
  '<script>(()=>{var s=new WebSocket("ws://"+location.host+"/__ssg_reload");s.onmessage=()=>location.reload();})()</script>';

function injectReload(html: string): string {
  return html.replace('</body>', `${RELOAD_SCRIPT}</body>`);
}

import { join } from 'path';
import { parsePosts } from './parser';
import { loadTemplates, renderPage, renderIndex, renderTagPage } from './renderer';
import { writeFile, copyStaticFiles, ensureDir } from './utils';
import { Post, SiteConfig } from './types';
import { generateRSS } from './rss';

export interface GenerateOptions {
  silent?: boolean;
  isDev?: boolean;
}

export function generate(config: SiteConfig, options: GenerateOptions = {}): void {
  const { source, output, templates: templatesDir } = config;
  const { silent = false, isDev = false } = options;

  const posts = parsePosts(source);
  const templates = loadTemplates(templatesDir);

  ensureDir(output);

  copyStaticFiles(source, output);

  if (!silent && !isDev) {
    console.log(`Found ${posts.length} posts`);
  }

  const indexHtml = renderIndex(templates, posts, config, isDev);
  writeFile(join(output, 'index.html'), indexHtml);

  for (const post of posts) {
    const html = renderPage(templates, post, config, posts, isDev);
    const outDir = join(output, post.slug);
    writeFile(join(outDir, 'index.html'), html);
  }

  const tagMap = new Map<string, Post[]>();
  for (const post of posts) {
    for (const tag of post.frontmatter.tags || []) {
      if (!tagMap.has(tag)) tagMap.set(tag, []);
      tagMap.get(tag)!.push(post);
    }
  }

  ensureDir(join(output, 'tags'));
  for (const [tag, tagPosts] of tagMap) {
    const html = renderTagPage(templates, tag, tagPosts, config, isDev);
    writeFile(join(output, 'tags', tag, 'index.html'), html);
  }

  const rss = generateRSS(posts, config);
  writeFile(join(output, 'rss.xml'), rss);

  if (!silent && !isDev) {
    console.log(`Generated site to ${output}`);
  }
}

import { Post, SiteConfig } from './types';

export function generateRSS(posts: Post[], config: SiteConfig): string {
  const url = config.siteUrl.replace(/\/+$/, '');
  const items = posts.slice(0, 20).map((p) => {
    const pubDate = p.frontmatter.date
      ? new Date(p.frontmatter.date).toUTCString()
      : new Date().toUTCString();
    return [
      '    <item>',
      `      <title>${escapeXml(p.frontmatter.title)}</title>`,
      `      <link>${url}/${p.slug}/</link>`,
      `      <description>${escapeXml(p.html.slice(0, 500))}</description>`,
      `      <pubDate>${pubDate}</pubDate>`,
      `      <guid>${url}/${p.slug}/</guid>`,
      ...(p.frontmatter.tags || []).map(
        (t) => `      <category>${escapeXml(t)}</category>`,
      ),
      '    </item>',
    ].join('\n');
  });

  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">',
    '  <channel>',
    `    <title>${escapeXml(config.siteTitle)}</title>`,
    `    <link>${url}</link>`,
    `    <description>${escapeXml(config.siteTitle)} - RSS Feed</description>`,
    `    <atom:link href="${url}/rss.xml" rel="self" type="application/rss+xml"/>`,
    `    <lastBuildDate>${new Date().toUTCString()}</lastBuildDate>`,
    items.join('\n'),
    '  </channel>',
    '</rss>',
  ].join('\n');
}

function escapeXml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

import http from 'http';
import { readFileSync, existsSync } from 'fs';
import { join, extname } from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar from 'chokidar';
import { generate } from './generator';
import { SiteConfig } from './types';

const MIME: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css',
  '.js': 'application/javascript',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.xml': 'application/xml',
  '.json': 'application/json',
};

export function startDevServer(config: SiteConfig): void {
  const { output, devPort: port } = config;

  const wss = new WebSocketServer({ noServer: true });
  const clients = new Set<WebSocket>();

  wss.on('connection', (ws) => {
    clients.add(ws);
    ws.on('close', () => clients.delete(ws));
  });

  function broadcast() {
    for (const c of clients) {
      c.send('reload');
    }
  }

  const server = http.createServer((req, res) => {
    const urlPath = (req.url || '/index.html').replace(/\?.*$/, '');
    const safePath = urlPath.replace(/^\/+/, '');
    const filePath = join(output, safePath || 'index.html');

    if (existsSync(filePath)) {
      const ext = extname(filePath);
      const contentType = MIME[ext] || 'application/octet-stream';
      try {
        const data = readFileSync(filePath);
        res.writeHead(200, { 'Content-Type': contentType });
        res.end(data);
      } catch {
        res.writeHead(500);
        res.end('Internal Server Error');
      }
    } else {
      // fallback to index.html for SPA-like routing
      const indexPath = join(output, 'index.html');
      if (existsSync(indexPath)) {
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(readFileSync(indexPath));
      } else {
        res.writeHead(404);
        res.end('Not Found');
      }
    }
  });

  server.on('upgrade', (req, socket, head) => {
    if (req.url === '/__ssg_reload') {
      wss.handleUpgrade(req, socket, head, (ws) => {
        wss.emit('connection', ws, req);
      });
    } else {
      socket.destroy();
    }
  });

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
    console.log(`Watching ${config.source} and ${config.templates}`);
  });

  const watcher = chokidar.watch([config.source, config.templates], {
    ignoreInitial: true,
    awaitWriteFinish: { stabilityThreshold: 100, pollInterval: 50 },
  });

  const rebuild = () => {
    console.log('Changes detected, rebuilding...');
    try {
      generate(config, { silent: true, isDev: true });
      broadcast();
      console.log('Rebuild complete');
    } catch (err) {
      console.error('Build error:', err);
    }
  };

  watcher.on('add', rebuild);
  watcher.on('change', rebuild);
  watcher.on('unlink', rebuild);

  process.on('SIGINT', () => {
    watcher.close();
    server.close();
    wss.close();
    process.exit(0);
  });
}

#!/usr/bin/env node

import { Command } from 'commander';
import { resolve } from 'path';
import { generate } from './generator';
import { startDevServer } from './server';
import { SiteConfig } from './types';

const program = new Command();

program
  .name('ssg')
  .description('Static site generator')
  .version('1.0.0')
  .option('-s, --source <dir>', 'source directory of markdown files', 'source')
  .option('-o, --output <dir>', 'output directory for generated HTML', 'dist')
  .option(
    '-t, --templates <dir>',
    'templates directory for Handlebars templates',
    'templates',
  )
  .option('-S, --serve', 'start dev server with live reload')
  .option('-p, --port <number>', 'dev server port', '3000')
  .option('--site-title <title>', 'site title', 'My Static Site')
  .option('--site-url <url>', 'site URL for RSS', 'http://localhost:3000')
  .action((opts) => {
    const config: SiteConfig = {
      source: resolve(process.cwd(), opts.source),
      output: resolve(process.cwd(), opts.output),
      templates: resolve(process.cwd(), opts.templates),
      siteTitle: opts.siteTitle,
      siteUrl: opts.siteUrl,
      devPort: parseInt(opts.port, 10) || 3000,
    };

    if (opts.serve) {
      generate(config, { silent: true, isDev: true });
      startDevServer(config);
    } else {
      generate(config);
    }
  });

program.parse();

